insert='''let gameCueTimer=null;\nconst GAME_CUE_META={\n  questionUnlock:{kind:"question",title:"Question unlocked",detail:"A new Seeker question type is available."},\n  cooldownReady:{kind:"question",title:"Questions ready",detail:"The global question cooldown has ended."},\n  relocationStart:{kind:"relocation",title:"Forced relocation",detail:"Move to a new legal hiding area before time runs out."},\n  relocationOvertime:{kind:"relocation",title:"Relocation overtime",detail:"Your overtime reveal has triggered. Keep moving and finish the relocation."},\n  relocationReady:{kind:"relocation",title:"Relocation target reached",detail:"You can press Ready once you have your new hiding spot."},\n  relocationComplete:{kind:"relocation",title:"Relocation complete",detail:"A fresh relocation interval has started."},\n  missionStart:{kind:"mission",title:"Mission started",detail:"Cross the Zone is active."},\n  missionComplete:{kind:"mission",title:"Mission complete",detail:"Power Charge earned."},\n  missionCancel:{kind:"mission",title:"Mission cancelled",detail:"The mission ended without a charge."},\n  matchStart:{kind:"match",title:"Match started",detail:"The hiding phase has begun."},\n  matchPause:{kind:"match",title:"Match paused",detail:"Gameplay timers are paused."},\n  matchResume:{kind:"match",title:"Match resumed",detail:"Gameplay timers are running again."}\n};\nfunction cueAllowedForRole(name){\n  if(!roomModeConnected())return true;\n  const role=roomRole();\n  if(name==="questionUnlock"||name==="cooldownReady")return role==="seeker";\n  if(name.startsWith("relocation"))return role==="hider";\n  if(name.startsWith("mission"))return role==="hider";\n  return true;\n}\nfunction showGameCue(name,detailOverride=""){\n  const meta=GAME_CUE_META[name];if(!meta)return;\n  const toast=document.getElementById("gameCueToast"),title=document.getElementById("gameCueTitle"),detail=document.getElementById("gameCueDetail");\n  if(!toast||!title||!detail)return;\n  clearTimeout(gameCueTimer);\n  toast.className=meta.kind;title.textContent=meta.title;detail.textContent=detailOverride||meta.detail;\n  void toast.offsetWidth;toast.classList.add("show");\n  gameCueTimer=setTimeout(()=>{toast.classList.remove("show");setTimeout(()=>{if(!toast.classList.contains("show"))toast.style.display="none";},230);},2700);\n}\nfunction triggerGameCue(name){\n  if(!cueAllowedForRole(name))return;\n  showGameCue(name);\n  playGameSound(name);\n}\n\n'''
s=s.replace(anchor,insert+anchor,1)

