insert='''function initializeQuestionCollapsibles(){\n  document.querySelectorAll(".questionCard").forEach(section=>{\n    if(section.dataset.collapsibleReady==="1")return;\n    const heading=section.querySelector(":scope > h3"),cost=section.querySelector(":scope > .questionCost"),notice=section.querySelector(":scope > .lockNotice");\n    if(!heading)return;\n    const toggle=document.createElement("button");toggle.type="button";toggle.className="questionCardToggle";toggle.setAttribute("aria-expanded","false");\n    const title=document.createElement("span");title.textContent=heading.textContent;\n    const chevron=document.createElement("span");chevron.className="questionChevron";chevron.textContent="⌄";\n    toggle.append(title,chevron);heading.replaceWith(toggle);\n    const body=document.createElement("div");body.className="questionCardBody";\n    let node=(notice||cost||toggle).nextSibling;\n    while(node){const next=node.nextSibling;body.appendChild(node);node=next;}\n    section.appendChild(body);section.classList.add("collapsed");section.dataset.collapsibleReady="1";\n    toggle.addEventListener("click",()=>{const collapsed=section.classList.toggle("collapsed");toggle.setAttribute("aria-expanded",String(!collapsed));});\n  });\n}\nfunction updateTopEconomy(){\n  const box=document.getElementById("topEconomy"),value=document.getElementById("topEconomyValue"),rate=document.getElementById("topEconomyRate");\n  if(!box||!value||!rate)return;\n  box.classList.remove("hider","seeker");\n  if(!roomModeConnected()){box.style.display="none";return;}\n  const role=roomRole();box.style.display="flex";box.classList.add(role==="hider"?"hider":"seeker");\n  if(role==="hider"){const n=Math.max(0,Number(hiderPowerCharges||0));value.textContent=`⚡ ${n} Power Charge${n===1?"":"s"}`;rate.textContent="";}\n  else{const n=seekerPointsBalance();value.textContent=`${n} Seeker Point${n===1?"":"s"}`;rate.textContent=`${pointsPerMinute}/min`;}\n}\nfunction settingDraftDirty(id){return settingsDirtyInputs.has(id);}\nfunction syncSettingValue(id,value){const el=document.getElementById(id);if(!el||settingDraftDirty(id)||document.activeElement===el)return;if(String(el.value)!==String(value))el.value=String(value);}\nfunction syncSettingChecked(id,value){const el=document.getElementById(id);if(!el||settingDraftDirty(id)||document.activeElement===el)return;el.checked=!!value;}\nfunction clearSettingDraft(ids){for(const id of ids)settingsDirtyInputs.delete(id);}\nfunction bindSettingDraftProtection(){\n  document.querySelectorAll('#view-settings input[type="number"]').forEach(el=>el.addEventListener("input",()=>settingsDirtyInputs.add(el.id)));\n  const linked=document.getElementById("firstQuestionOnHideEnd");if(linked)linked.addEventListener("change",()=>settingsDirtyInputs.add(linked.id));\n}\n\n'''
