once('''document.getElementById("hideTimeMinutes").addEventListener("input",syncHideTimeControls);\ndocument.getElementById("firstQuestionOnHideEnd").addEventListener("change",syncHideTimeControls);\n''','''document.getElementById("hideTimeMinutes").addEventListener("input",()=>{syncHideTimeControls();if(document.getElementById("firstQuestionOnHideEnd").checked){settingsDirtyInputs.add("firstUnlockMinutes");settingsDirtyInputs.add("gridUnlockMinutes");}});\ndocument.getElementById("firstQuestionOnHideEnd").addEventListener("change",()=>{syncHideTimeControls();settingsDirtyInputs.add("firstUnlockMinutes");settingsDirtyInputs.add("gridUnlockMinutes");});\n''','linked hide draft listeners')

# Clear draft flags only after successful Apply so synced room state can resume updating those controls.
once('''  hidingSettings={duration:hideMinutes*60,firstQuestionOnEnd:linked};\n  unlockTimes={grid:vals[0]*60,nearest:vals[1]*60,towerRadius:vals[2]*60,landmark:vals[3]*60,marker:vals[4]*60};\n  questionCooldownSeconds=cooldownMinutes*60;\n  updateScheduleInputs();renderMatchTimer();notifyRoomGameStateChanged();\n''','''  hidingSettings={duration:hideMinutes*60,firstQuestionOnEnd:linked};\n  unlockTimes={grid:vals[0]*60,nearest:vals[1]*60,towerRadius:vals[2]*60,landmark:vals[3]*60,marker:vals[4]*60};\n  questionCooldownSeconds=cooldownMinutes*60;\n  clearSettingDraft(["hideTimeMinutes","firstQuestionOnHideEnd","firstUnlockMinutes","unlockIntervalMinutes","gridUnlockMinutes","nearestUnlockMinutes","towerRadiusUnlockMinutes","landmarkUnlockMinutes","markerUnlockMinutes","questionCooldownMinutes"]);\n  updateScheduleInputs();renderMatchTimer();notifyRoomGameStateChanged();\n''','clear timing draft on apply')
once('''  questionCosts=nextCosts;updateQuestionCostInputs();updateQuestionEconomy();notifyRoomGameStateChanged();\n''','''  questionCosts=nextCosts;clearSettingDraft(Object.keys(ids));updateQuestionCostInputs();updateQuestionEconomy();notifyRoomGameStateChanged();\n''','clear cost drafts on apply')
once('''  relocationSettings={firstAt:first*60,interval:interval*60,window:windowMin*60,minDistance,skipBelow};\n  if(!relocationState.active&&!missionState.active){relocationState.nextAt=relocationState.index===0?relocationSettings.firstAt:currentMatchSeconds()+relocationSettings.interval;}\n  resetLocalRelocationPlan();renderMatchTimer();notifyRoomGameStateChanged();\n''','''  relocationSettings={firstAt:first*60,interval:interval*60,window:windowMin*60,minDistance,skipBelow};\n  if(!relocationState.active&&!missionState.active){relocationState.nextAt=relocationState.index===0?relocationSettings.firstAt:currentMatchSeconds()+relocationSettings.interval;}\n  clearSettingDraft(["relocationFirstMinutes","relocationIntervalMinutes","relocationWindowMinutes","relocationMinDistance","relocationSkipBelow"]);\n  resetLocalRelocationPlan();updateRelocationSettingsInputs();renderMatchTimer();notifyRoomGameStateChanged();\n''','clear relocation drafts on apply')

